import pandas as pd
sql_query = """
SELECT 
    "[Employee Master[Employee Name]]" as employee_name,
    "[Employee Master[Time Since Last Promotion]]" as time_since_promotion
FROM enterprise_data
"""
df = execute_sql_query(sql_query)
if df.empty:
    result = {'type': 'string', 'value': 'No employee records found in the system.'}
else:
    result_lines = ['Time Since Last Promotion for Each Employee (in years):\n']
    result_lines.append('-' * 60)
    for idx, row in df.iterrows():
        emp_name = row['employee_name']
        time_value = row['time_since_promotion']
        # Format the value, handle NULL/None cases
        if pd.notna(time_value):
            result_lines.append(f'{emp_name}: {time_value:.2f} years')
        else:
            result_lines.append(f'{emp_name}: N/A')
    result_lines.append('-' * 60)
    result = {'type': 'string', 'value': '\n'.join(result_lines)}
